  parent.grabC = { type: 'SendMotorCommandEnvCN', source: 'unit_grabber.outCommand', target: 'transElevator.inCommand' };
  // EnvConnector: spePresenceC : ReadPresenceEnvCN bindings entryStock.outPresence = unit_speSens.inPresence
  parent.spePresenceC = { type: 'ReadPresenceEnvCN', source: 'entryStock.outPresence', target: 'unit_speSens.inPresence' };
