// Scenario: Scenario_ObstacleHandling_Unit1
class Scenario_ObstacleHandling_Unit1 extends Scenario {
  constructor(name = 'Scenario_ObstacleHandling_Unit1', opts = {}) {
    super(name, { ...opts, scenarioType: 'scenario' });
    this.sceneSequence = [
      'SCN_ObstacleStop_Unit1',
      'SCN_ObstacleResume_Unit1',
    ];
  }

  async execute(ctx) {
    const results = [];
    for (const sceneName of this.sceneSequence) {
      const SceneClass = ctx.scenes?.[sceneName];
      if (!SceneClass) { results.push({ scene: sceneName, status: 'NOT_FOUND' }); continue; }
      const scene = typeof SceneClass === 'function' ? new SceneClass() : SceneClass;
      const preOk = scene.validatePreConditions(ctx);
      if (!preOk) { results.push({ scene: sceneName, status: 'PRECONDITION_FAIL' }); continue; }
      // Execute scene logic (start → finish via ON/THEN/SEND chain)
      if (ctx.envActivities) {
        const chain = ctx.envActivities.handleSignal(scene.opts?.startEvent || scene.startEvent, {}, ctx);
        // Process signal chain until finish event
        let pending = chain.filter(r => r.signal);
        let maxIter = 100;
        while (pending.length > 0 && maxIter-- > 0) {
          const next = [];
          for (const p of pending) {
            const sub = ctx.envActivities.handleSignal(p.signal, p.data || {}, ctx);
            next.push(...sub.filter(r => r.signal));
          }
          pending = next;
        }
      }
      // Wait for postconditions to be met (reactive evaluation)
      let postOk = false;
      const startTime = Date.now();
      const timeout = 2000; // 2 seconds max timeout
      while (Date.now() - startTime < timeout) {
        postOk = scene.validatePostConditions(ctx);
        if (postOk) break;
        await new Promise(resolve => setTimeout(resolve, 5));
      }
      results.push({ scene: sceneName, status: postOk ? 'PASS' : 'POSTCONDITION_FAIL' });
    }
    return results;
  }
}

