  model.envConnectorDefs['DetectPieceColorEnvCN'] = ECN_DetectPieceColorEnvCN;
  model.envConnectorDefs['DetectParameterEnvCN'] = ECN_DetectParameterEnvCN;
  model.envConnectorDefs['ReadParameterEnvCN'] = ECN_ReadParameterEnvCN;
